charBubbleCSS:
:root {
    --bubble-me-bg: #FAEBF3;
    --bubble-me-color: #050F00;
    --bubble-me-border: 1px solid #B9B8B9;
    --bubble-me-shadow: inset 0 1.5px 3px rgba(255,255,255,0.7),inset 0 -10px 5px rgba(150, 150, 150,0.1),0 3px 4px rgba(0, 0, 0, 0.15);
    --bubble-me-radius: 10px;

    --bubble-them-bg: #F5F5F5;
    --bubble-them-color: #050F00;
    --bubble-them-border: 1px solid #c4c4c4;
    --bubble-them-shadow: inset 0 1.5px 3px rgba(255,255,255,0.7),inset 0 -10px 5px rgba(150, 150, 150,0.1),0 3px 4px rgba(0, 0, 0, 0.15);
    --bubble-them-radius: 10px;
}

/* ===== 消息容器全局布局 ===== */
.message-container {
  margin-bottom: 1px !important;
  display: flex;
  align-items: flex-end;
  gap: 5px !important;
  flex-direction: column !important;
  margin-top: 0 !important;
  margin-bottom: 7px !important;
}
.message-container.sent {
  justify-content: flex-end;
}
.message-container.received {
  justify-content: flex-start;
}
/* 同账号连续消息间距 */
.message-container.received + .message-container.received,
.message-container.sent + .message-container.sent {
  margin-top: 14px !important;
}
/* 切换账号消息间距 */
.message-container.received + .message-container.sent,
.message-container.sent + .message-container.received {
  margin-top: 20px !important;
}

/* 隐藏头像 */
.msg-avatar-custom {
    display: none !important;
}

/* ===== 接收方气泡 原版复古样式 ===== */
.bubble-them-custom {
    background: #F5F5F5 !important;
    border: 1px solid #c4c4c4 !important;
    border-radius: 10px !important;
    padding: 6px 10px !important;
    font-size: 11px !important;
    color: #050F00 !important;
    max-width: 65%;
    word-wrap: break-word;
    position: relative !important;
    box-shadow: 
    inset 0 1.5px 3px rgba(255,255,255,0.7),
    inset 0 -10px 5px rgba(150, 150, 150,0.1),
    0 3px 4px rgba(0, 0, 0, 0.15) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    text-shadow: none !important;
}
/* 接收方左下角角标 */
.bubble-them-custom::before {
  content: "" !important;
  position: absolute !important;
  background-size: contain !important;
  left: -10px !important;
  top: 7px !important;
  width: 18px !important;
  height: 18px !important;
  background-image: url('https://i.postimg.cc/ZRd9qXWx/wu-biao-ti36-20251201221338.png') !important;
  z-index: 1 !important;
}

/* ===== 发送方气泡 原版复古样式 ===== */
.bubble-me-custom {
    background: #FAEBF3 !important;
    border: 1px solid #B9B8B9 !important;
    border-radius: 10px !important;
    padding: 6px 10px !important;
    font-size: 11px !important;
    color: #050F00 !important;
    max-width: 65%;
    word-wrap: break-word;
    position: relative !important;
    box-shadow: 
    inset 0 1.5px 3px rgba(255,255,255,0.7),
    inset 0 -10px 5px rgba(150, 150, 150,0.1),
    0 3px 4px rgba(0, 0, 0, 0.15) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    text-shadow: none !important;
}
/* 移除自带对勾 */
.bubble-me-custom::after {
  display: none !important;
}
/* 发送方右下角角标 */
.bubble-me-custom::before {
  content: "" !important;
  position: absolute !important;
  background-size: contain !important;
  right: -10px !important;
  top: 7px !important;
  width: 18px !important;
  height: 18px !important;
  background-image: url('https://i.postimg.cc/Wb5BhCmp/wu-biao-ti36-20251201214524.png') !important;
  z-index: 1 !important;
}

/* 全局隐藏气泡内所有时间戳 */
.bubble-me-custom .timestamp,.bubble-me-custom .time,.bubble-me-custom .message-time,.bubble-me-custom .msg-time,.bubble-me-custom [class*="time"],
.bubble-them-custom .timestamp,.bubble-them-custom .time,.bubble-them-custom .message-time,.bubble-them-custom .msg-time,.bubble-them-custom [class*="time"] {
  display: none !important;
}

/* ===== 表情包专属适配 ===== */
.bubble-me-custom:has(img),
.bubble-them-custom:has(img) {
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  max-width: none !important;
  width: auto !important;
}
.bubble-me-custom:has(img) img,
.bubble-them-custom:has(img) img {
  display: block !important;
  border-radius: 0 !important;
  max-width: 170px !important;
  height: auto !important;
  object-fit: contain !important;
}
/* 表情包隐藏角标 */
.bubble-me-custom:has(img)::before,
.bubble-them-custom:has(img)::before {
  display: none !important;
}
/* 表情包彻底隐藏时间 */
.bubble-me-custom:has(img) [class*="time"], 
.bubble-them-custom:has(img) [class*="time"] {
  display: none !important;
  visibility: hidden !important;
  opacity: 0 !important; 
}

/* 气泡统一清除多余滤镜 */
.message-bubble,.message-container {
  filter: none !important;
}

