xinshengCustomCss:
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { 
    margin: 0 !important; padding: 0 !important; border: none !important; 
    display: block !important; box-shadow: none !important; 
    white-space: pre-wrap !important; outline: none !important; 
    background: transparent !important; border-radius: 0 !important; 
}

.xt-root {
    position: relative !important;
    width: 100% !important; max-width: 420px !important;
    height: 700px !important;
    margin: 0 auto !important;
    background: 
        radial-gradient(circle at 20% 15%, rgba(0,0,0,0.035) 0%, transparent 40%),
        radial-gradient(circle at 80% 85%, rgba(0,0,0,0.025) 0%, transparent 40%),
        #ffffff !important;
    color: #2a2a2a !important;
    font-family: 'SimSun', 'STSong', serif !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    scrollbar-width: thin !important;
    scrollbar-color: #c8c8c8 #ffffff !important;
    border: 1px solid #e0e0e0 !important;
    border-radius: 0 !important;
}
.xt-root::-webkit-scrollbar { width: 3px !important; }
.xt-root::-webkit-scrollbar-track { background: #ffffff !important; }
.xt-root::-webkit-scrollbar-thumb { background: #c8c8c8 !important; }
.xt-root::before {
    content: '' !important;
    position: fixed !important; inset: 0 !important;
    background-image: 
        repeating-radial-gradient(circle at 30% 20%, rgba(0,0,0,0.014) 0, rgba(0,0,0,0.014) 1px, transparent 1px, transparent 3px),
        repeating-radial-gradient(circle at 70% 60%, rgba(0,0,0,0.01) 0, rgba(0,0,0,0.01) 1px, transparent 1px, transparent 4px) !important;
    pointer-events: none !important;
    z-index: 999 !important;
    mix-blend-mode: multiply !important;
}

/* ═══ 顶部刊头 ═══ */
.xt-text:nth-of-type(1) {
    position: relative !important;
    padding: 40px 22px 0 22px !important;
    color: #808080 !important; font-size: 9px !important; letter-spacing: 4px !important;
    font-family: 'Georgia', serif !important; font-style: italic !important;
}
.xt-text:nth-of-type(1)::before {
    content: '' !important;
    position: absolute !important;
    top: 24px !important; left: 22px !important;
    width: 40px !important; height: 3px !important;
    background: #0a0a0a !important;
    box-shadow: 46px 0 0 #0a0a0a, 56px 0 0 #b0b0b0, 62px 0 0 #0a0a0a !important;
}

.xt-text:nth-of-type(2) {
    padding: 8px 22px 0 22px !important;
    color: #0a0a0a !important; font-size: 34px !important;
    font-family: 'Didot', 'Bodoni MT', 'Playfair Display', 'Georgia', serif !important;
    font-weight: 300 !important;
    letter-spacing: 1px !important; line-height: 0.95 !important;
}

.xt-text:nth-of-type(3) {
    margin: 12px 22px 0 22px !important;
    padding: 10px 0 0 0 !important;
    color: #707070 !important; font-size: 9px !important; letter-spacing: 3px !important;
    font-family: 'Georgia', serif !important; font-style: italic !important;
    border-top: 1px solid #d8d8d8 !important;
}

.xt-text:nth-of-type(4) {
    padding: 4px 22px 0 22px !important;
    text-align: right !important;
    color: #808080 !important; font-size: 8.5px !important; letter-spacing: 2px !important;
    font-family: 'Georgia', serif !important;
}

.xt-text:nth-of-type(5) {
    margin: 14px 22px 0 22px !important;
    padding: 8px 12px !important;
