xinshengCustomCss:
/* ===== 第1段 · 根主题 ===== */
.xt-root {
  --xt-bg: linear-gradient(175deg, #16161a, #0b0b0d);
  --xt-text: #f5f5f3;
  --xt-text-sub: rgba(245,245,243,0.72);
  --xt-text-muted: rgba(245,245,243,0.45);
  --xt-accent: #c9a86a;
  --xt-accent-bg: rgba(201,168,106,0.08);
  --xt-border: rgba(255,255,255,0.08);
  --xt-radius: 20px;
  --xt-radius-sm: 12px;
  --xt-font: -apple-system, BlinkMacSystemFont, "PingFang SC", "Segoe UI", sans-serif;
  background-color: #0b0b0d;
  border-radius: 34px;
  box-shadow:
    0 0 0 7px #0c0c0e,
    0 0 0 8px rgba(255,255,255,0.14),
    0 0 0 9px rgba(255,255,255,0.04),
    0 36px 90px rgba(0,0,0,0.7);
}

.xt-text-phonebar, .xt-text-userinfo,
.xt-text-tweet, .xt-text-imgdesc, .xt-text-statline, .xt-text-cmt_all,
.xt-text-musicsong, .xt-text-musiclyric, .xt-text-musicfeel,
.xt-text-douyin_video, .xt-text-douyin_bgm, .xt-text-douyin_caption,
.xt-text-douyin_stats, .xt-text-douyin_cmt,
.xt-text-zhihu_q, .xt-text-zhihu_a,
.xt-text-bili_title, .xt-text-bili_rest, .xt-text-bili_mycmt,
.xt-text-xh_title, .xt-text-xh_rest, .xt-text-xh_mycmt,
.xt-text-game,
.xt-text-album_1, .xt-text-album_2, .xt-text-album_3,
.xt-text-location,
.xt-text-order, .xt-text-delivery, .xt-text-wallet_app,
.xt-text-bills_expense, .xt-text-bills_income,
.xt-text-health_steps, .xt-text-health_sleep,
.xt-text-calendar_note, .xt-text-alarm,
.xt-text-chat_a_title, .xt-text-chat_b_title, .xt-text-chat_g_title,
.xt-text-call, .xt-text-fav,
.xt-text-p1body, .xt-text-p1cmt, .xt-text-p2body, .xt-text-p2cmt,
.xt-text-pollq, .xt-text-pollopt, .xt-text-pollinfo,
.xt-text-trends_hot, .xt-text-trends_view, .xt-text-history,
.xt-text-recommend_reminder,
.xt-text-reading_title, .xt-text-reading_quote, .xt-text-reading_note,
.xt-text-letter,
.xt-text-porn_title, .xt-text-porn_desc, .xt-text-porn_feel,
.xt-text-screentime, .xt-text-sms_1, .xt-text-sms_2, .xt-text-sms_3,
.xt-text-notify_1, .xt-text-notify_2, .xt-text-notify_3,
.xt-text-quickpanel,
.xt-text-weather_stamp, .xt-text-bottomnav {
  white-space: pre-wrap;
}
/* ===== 第2段 · 卡片与帖子 ===== */
.xt-card {
  background: #16161a;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 20px;
  margin: 8px 10px;
  padding: 14px;
  box-shadow: 0 4px 16px rgba(0,0,0,0.25);
}
.xt-card-title {
  color: #c9a86a;
  font-size: 11px; font-weight: 700;
  letter-spacing: 2.5px;
  padding: 0 0 8px 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  border-left: 3px solid #c9a86a;
}
.xt-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 4px 0 10px;
}
.xt-avatar {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 2px solid #c9a86a;
  box-shadow: 0 0 0 3px rgba(201,168,106,0.15);
  object-fit: cover;
  flex-shrink: 0;
}
.xt-name {
  flex: 1;
  font-size: 14px; font-weight: 800;
  color: #f5f5f3;
  line-height: 1.5;
}
.xt-text-tweet {
  font-size: 17px; font-weight: 550;
  line-height: 1.8; letter-spacing: 0.3px;
  color: #f5f5f3;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.xt-text-imgdesc {
  padding: 20px 14px;
  background: linear-gradient(180deg, #1c1c20, #19191d);
  border: 1px solid rgba(201,168,106,0.2);
  border-radius: 12px;
  margin: 10px 0;
  font-size: 13px;
  text-align: center;
  color: rgba(245,245,243,0.7);
}
.xt-text-statline {
  padding: 8px 0;
  font-size: 12.5px; letter-spacing: 1px;
  color: #c9a86a;
  text-align: center;
  border-top: 1px dashed rgba(201,168,106,0.25);
  border-bottom: 1px dashed rgba(201,168,106,0.25);
}
.xt-text-cmt_all {
  padding: 10px 0 2px;
  font-size: 13.5px;
  line-height: 2.1;
  color: rgba(245,245,243,0.75);
  border-top: 2px solid rgba(201,168,106,0.4);
  margin-top: 8px;
}

/* ===== 第3段 · 知乎 ===== */
.xt-text-zhihu_q {
  padding: 14px 16px 12px;
  background: #f9fafc;
  border: 1px solid #0084ff;
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  font-size: 14px; font-weight: 700;
  color: #0084ff;
  line-height: 1.6;
  margin: 0 !important;
}
.xt-text-zhihu_a {
  padding: 12px 16px 14px;
  background: #f9fafc;
  border: 1px solid #0084ff;
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 13.5px; line-height: 1.95;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-zhihu_a::first-line {
  font-weight: 700;
  color: #18191a;
}
/* ===== 第4段 · B站 ===== */
.xt-text-bili_title {
  padding: 14px 16px 12px;
  background: #f9fafc;
  border: 1px solid #00a1d6;
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  font-size: 14px; font-weight: 700;
  color: #00a1d6;
  line-height: 1.6;
  margin: 0 !important;
}
.xt-text-bili_rest {
  position: relative;
  padding: 12px 16px 28px;
  background: #f9fafc;
  border: 1px solid #00a1d6;
  border-top: none;
  border-bottom: none;
  border-radius: 0;
  font-size: 13px; line-height: 2;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-bili_rest::after {
  content: "";
  position: absolute;
  left: 16px; right: 16px; bottom: 10px;
  height: 3px;
  border-radius: 2px;
  background: linear-gradient(90deg, #00a1d6 0 65%, #e0e2e6 65% 100%);
}
.xt-text-bili_mycmt {
  padding: 8px 12px 10px;
  background: #f0f6fa;
  border: 1px solid #00a1d6;
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 12.5px; line-height: 1.75;
  color: #18191a;
  margin: 0 !important;
}
.xt-text-bili_mycmt::before {
  content: "我的评论";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px;
  color: #00a1d6;
  margin-bottom: 4px;
}


/* ===== 第5段 · 微信 ===== */
.xt-text-chat_a_title,
.xt-text-chat_b_title,
.xt-text-chat_g_title {
  text-align: center;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #f5f5f3;
  padding: 4px 0 10px;
  margin-bottom: 10px;
  border-bottom: 1px solid rgba(7,193,96,0.35);
}
.xt-bubble,
.xt-bubble-left,
.xt-bubble-right,
.xt-bubble-body {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
}
.xt-bubbles {
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.xt-bubble-left {
  align-self: flex-start;
  max-width: 82%;
  background: #2a2a30 !important;
  border-radius: 12px 12px 12px 4px !important;
  padding: 7px 11px;
  font-size: 12.5px; line-height: 1.65;
  color: #f5f5f3 !important;
}
.xt-bubble-right {
  align-self: flex-end;
  max-width: 82%;
  background: linear-gradient(135deg, #07c160, #06a04f) !important;
  border-radius: 12px 12px 4px 12px !important;
  padding: 7px 11px;
  font-size: 12.5px; line-height: 1.65;
  color: #ffffff !important;
}
/* ===== 第6段 · 通话/收藏/好友 ===== */
.xt-text-call {
  position: relative;
  padding: 10px 12px 10px 14px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 12px; line-height: 1.9;
  color: rgba(245,245,243,0.8);
}
.xt-text-call::first-line {
  color: #c9a86a;
  font-weight: 700;
}
.xt-text-call::after {
  content: "";
  position: absolute;
  right: 12px; top: 14px;
  width: 7px; height: 7px;
  border-radius: 50%;
  background: #e74c3c;
  box-shadow: 0 0 4px rgba(231,76,60,0.5);
}
.xt-text-fav {
  position: relative;
  padding: 10px 14px 10px 34px;
  background: #211f1b;
  border: 1px solid rgba(201,168,106,0.15);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2;
  color: rgba(245,245,243,0.8);
}
.xt-text-fav::before {
  content: "★";
  position: absolute;
  left: 13px; top: 50%;
  transform: translateY(-50%);
  color: #e6b46a;
  font-size: 15px;
}
.xt-text-p1avt, .xt-text-p2avt {
  display: inline-block;
  width: 40px; height: 40px;
  border-radius: 50%;
  background: linear-gradient(135deg, #323238, #242428);
  border: 1px solid rgba(201,168,106,0.5);
  font-size: 21px; line-height: 40px;
  text-align: center; vertical-align: top;
  margin: 4px 8px 4px 0;
  padding: 0;
}
.xt-text-p1info, .xt-text-p2info {
  display: inline-block;
  padding: 9px 12px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 10px;
  font-size: 14px; font-weight: 700;
  color: #f5f5f3;
  vertical-align: top; line-height: 1.4;
}
.xt-text-p1body, .xt-text-p2body {
  padding: 12px 0;
  font-size: 14px; line-height: 1.75;
  color: rgba(245,245,243,0.8);
  border-bottom: 1px solid rgba(255,255,255,0.07);
}
.xt-text-p1cmt, .xt-text-p2cmt {
  padding: 10px 0 2px;
  font-size: 12.5px; line-height: 2.1;
  color: rgba(245,245,243,0.55);
  border-top: 2px solid rgba(201,168,106,0.4);
  margin-top: 8px;
}
/* ===== 第7段 · 投票/热搜/搜索/引用/推荐 ===== */
.xt-text-pollq {
  padding: 10px 14px 10px 16px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 15px; font-weight: 700;
  color: #f5f5f3;
}
.xt-text-pollopt {
  position: relative;
  padding: 10px 14px 10px 34px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 14px; line-height: 2.2;
  color: rgba(245,245,243,0.75);
}
.xt-text-pollopt::before {
  content: "";
  position: absolute;
  left: 14px; top: 50%;
  transform: translateY(-50%);
  width: 12px; height: 12px;
  border-radius: 50%;
  border: 2px solid rgba(201,168,106,0.5);
  background: radial-gradient(circle, #c9a86a 0 40%, transparent 45%);
}
.xt-text-pollopt::first-line { color: #f5f5f3; font-weight: 700; }
.xt-text-pollinfo {
  padding: 8px 14px;
  background: #1b1b1f;
  border-radius: 10px;
  font-size: 12px;
  color: rgba(245,245,243,0.5);
}
.xt-text-trends_hot {
  padding: 12px 14px 12px 16px;
  background: linear-gradient(180deg, #201f1c, #1a1916);
  border: 1px solid rgba(201,168,106,0.12);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 14px; line-height: 2.5;
  color: rgba(245,245,243,0.85);
}
.xt-text-trends_hot::before {
  content: "实时热榜";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #c9a86a;
  margin-bottom: 8px;
}
.xt-text-trends_view {
  padding: 10px 14px 10px 16px;
  background: #1b1a18;
  border: 1px solid rgba(201,168,106,0.15);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin-top: 8px;
}
.xt-text-trends_view::before {
  content: "我的看法";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2.4px;
  color: #c9a86a;
  margin-bottom: 6px;
}
.xt-text-history {
  position: relative;
  padding: 12px 14px 12px 36px;
  background: #1c1c20;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 2px dotted rgba(201,168,106,0.6);
  border-radius: 12px;
  font-size: 13px; line-height: 2.1;
  color: rgba(245,245,243,0.55);
}
.xt-text-history::before {
  content: "";
  position: absolute;
  left: 13px; top: 50%;
  transform: translateY(-50%);
  width: 10px; height: 10px;
  border: 1.5px solid rgba(245,245,243,0.4);
  border-radius: 50%;
}
.xt-text-history::after {
  content: "";
  position: absolute;
  left: 22px; top: calc(50% + 4px);
  width: 6px; height: 1.5px;
  background: rgba(245,245,243,0.4);
  transform: rotate(45deg);
}
.xt-quote {
  position: relative;
  padding: 14px 16px 14px 22px;
  background: linear-gradient(135deg, #232018, #1f1c16);
  border: 1px solid rgba(201,168,106,0.22);
  border-radius: 12px;
  font-size: 14px; line-height: 1.9;
  color: #f5f5f3;
  font-style: italic;
}
.xt-text-recommend_reminder {
  padding: 10px 14px 10px 16px;
  background: #1e1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: rgba(245,245,243,0.75);
}
/* ===== 第8段 · 微信读书+备忘录 ===== */
.xt-text-reading_title {
  padding: 14px 16px;
  background: linear-gradient(135deg, #0f1f18, #12161a);
  border: 1px solid rgba(46,175,79,0.25);
  border-left: 3px solid #2eaf4f;
  border-bottom: none;
  border-radius: 14px 14px 0 0;
  font-size: 14px; font-weight: 700;
  color: #4ade80;
  margin: 0 !important;
}
.xt-text-reading_quote {
  padding: 10px 16px;
  background: #0e1f17;
  border: 1px solid rgba(46,175,79,0.25);
  border-top: none;
  border-left: 3px solid #2eaf4f;
  border-radius: 0;
  font-style: italic;
  font-size: 13px; line-height: 1.9;
  color: #a7f3d0;
  margin: 0 !important;
}
.xt-text-reading_note {
  padding: 10px 16px 14px;
  background: #12161a;
  border: 1px solid rgba(46,175,79,0.25);
  border-top: none;
  border-radius: 0 0 14px 14px;
  font-size: 13px; line-height: 1.9;
  color: rgba(245,245,243,0.85);
  margin: 0 !important;
}
.xt-text-reading_note::before {
  content: "我的笔记";
  display: block;
  font-size: 10px; font-weight: 700;
  letter-spacing: 2px;
  color: #4ade80;
  margin-bottom: 6px;
}
.xt-text-letter {
  position: relative;
  padding: 46px 18px 32px;
  background-color: #fbf7ec;
  background-image:
    linear-gradient(180deg, rgba(255,255,255,0.6), transparent 30%),
    linear-gradient(180deg, transparent, rgba(210,190,150,0.15));
  border: 1px solid rgba(200,180,140,0.5);
  border-radius: 18px;
  box-shadow:
    0 14px 36px rgba(0,0,0,0.55),
    inset 0 1px 0 rgba(255,255,255,0.8),
    inset 0 0 60px rgba(230,215,180,0.2);
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", sans-serif;
  font-size: 15px;
  line-height: 1.9;
  letter-spacing: 0.3px;
  color: #3a3428;
  white-space: pre-wrap;
}
.xt-text-letter::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 32px;
  background:
    radial-gradient(circle 3px at 16px 16px, rgba(120,100,70,0.35), transparent),
    radial-gradient(circle 3px at 28px 16px, rgba(120,100,70,0.35), transparent),
    radial-gradient(circle 3px at 40px 16px, rgba(120,100,70,0.35), transparent),
    linear-gradient(180deg, #f0e9d6, #e4dbc2);
  border-radius: 18px 18px 0 0;
  border-bottom: 1px solid rgba(200,180,140,0.35);
}
.xt-text-letter::after {
  content: "";
  position: absolute;
  left: 18px; right: 18px; bottom: 14px;
  height: 1px;
  background: linear-gradient(90deg, rgba(180,160,120,0.5), transparent 70%);
}
/* ===== 第9段 · 系统区 ===== */
.xt-text-screentime {
  padding: 12px 14px;
  background: #1c1e22;
  border: 1px solid rgba(255,255,255,0.07);
  border-left: 3px solid #c9a86a;
  border-radius: 12px;
  font-size: 13.5px; line-height: 2.1;
  color: rgba(245,245,243,0.8);
}
.xt-text-sms_1 {
  align-self: flex-start;
  max-width: 88%;
  background: #1e3a2e;
  border-radius: 14px 14px 14px 4px;
  padding: 9px 13px;
  font-size: 13px; line-height: 1.75;
  color: #f0f5f1;
  margin: 4px 0 10px;
}
.xt-text-sms_1::first-line {
  display: block;
  font-size: 10.5px;
  color: rgba(240,245,241,0.55);
  margin-bottom: 4px;
}
.xt-text-sms_2 {
  align-self: flex-start;
  max-width: 88%;
  background: #2a2a30;
  border-radius: 14px 14px 14px 4px;
  padding: 9px 13px;
  font-size: 13px; line-height: 1.75;
  color: #f5f5f3;
  margin: 0 0 10px;
}
.xt-text-sms_2::first-line {
  display: block;
  font-size: 10.5px;
  color: rgba(245,245,243,0.5);
  margin-bottom: 4px;
}
.xt-text-sms_3 {
  align-self: flex-end;
  max-width: 88%;
  background: #0a5cb8;
  border-radius: 14px 14px 4px 14px;
  padding: 9px 13px;
  font-size: 13px; line-height: 1.75;
  color: #ffffff;
  margin: 0 0 4px;
  text-align: right;
}
.xt-text-sms_3::first-line {
  display: block;
  font-size: 10.5px;
  color: rgba(255,255,255,0.6);
  margin-bottom: 4px;
  text-align: right;
}
.xt-text-notify_1,
.xt-text-notify_2,
.xt-text-notify_3 {
  position: relative;
  padding: 10px 14px 10px 20px;
  background: #1d2023;
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 14px;
  font-size: 12.5px; line-height: 1.75;
  color: rgba(245,245,243,0.8);
  margin-bottom: 8px;
}
.xt-text-notify_1::before,
.xt-text-notify_2::before,
.xt-text-notify_3::before {
  content: "";
  position: absolute;
  left: 7px; top: 17px;
  width: 6px; height: 6px;
  border-radius: 50%;
  background: #c9a86a;
  box-shadow: 0 0 0 3px rgba(201,168,106,0.18);
}
.xt-text-quickpanel {
  padding: 12px 16px;
  background: linear-gradient(135deg, #1d2023, #17191c);
  border: 1px solid rgba(159,178,192,0.2);
  border-left: 3px solid #9fb2c0;
  border-radius: 12px;
  font-size: 13px; line-height: 2.6;
  color: rgba(245,245,243,0.8);
  text-align: center;
}
.xt-text-weather_stamp {
  padding: 14px 16px;
