.xt-text:nth-of-type(43):hover::before,
.xt-text:nth-of-type(45):hover::before,
.xt-text:nth-of-type(47):hover::before,
.xt-text:nth-of-type(49):hover::before,
.xt-text:nth-of-type(51):hover::before,
.xt-text:nth-of-type(53):hover::before,
.xt-text:nth-of-type(55):hover::before { color: #0a0a0a !important; }
.xt-text:nth-of-type(41):hover::after,
.xt-text:nth-of-type(43):hover::after,
.xt-text:nth-of-type(45):hover::after,
.xt-text:nth-of-type(47):hover::after,
.xt-text:nth-of-type(49):hover::after,
.xt-text:nth-of-type(51):hover::after,
.xt-text:nth-of-type(53):hover::after,
.xt-text:nth-of-type(55):hover::after {
    content: '♫  playing' !important; color: #0a0a0a !important;
}

/* 展开面板 · 更浅一层灰 */
.xt-text:nth-of-type(42),
.xt-text:nth-of-type(44),
.xt-text:nth-of-type(46),
.xt-text:nth-of-type(48),
.xt-text:nth-of-type(50),
.xt-text:nth-of-type(52),
.xt-text:nth-of-type(54),
.xt-text:nth-of-type(56) {
    max-height: 0 !important;
    overflow: hidden !important;
    margin: 0 12px !important;
    padding: 0 20px 0 56px !important;
    color: #3a3a3a !important;
    font-size: 10.5px !important;
    line-height: 2 !important;
    letter-spacing: 0.5px !important;
    font-family: 'Courier New', 'Georgia', monospace !important;
    background: 
        linear-gradient(to right, rgba(0,0,0,0.03), transparent 90%),
        #e0e0e0 !important;
    transition: max-height 0.55s cubic-bezier(0.16, 1, 0.3, 1), padding 0.4s !important;
    border-bottom: 1px solid #d0d0d0 !important;
    border-left: 2px solid transparent !important;
}
.xt-text:nth-of-type(41):hover + .xt-text:nth-of-type(42),
.xt-text:nth-of-type(43):hover + .xt-text:nth-of-type(44),
.xt-text:nth-of-type(45):hover + .xt-text:nth-of-type(46),
.xt-text:nth-of-type(47):hover + .xt-text:nth-of-type(48),
.xt-text:nth-of-type(49):hover + .xt-text:nth-of-type(50),
.xt-text:nth-of-type(51):hover + .xt-text:nth-of-type(52),
.xt-text:nth-of-type(53):hover + .xt-text:nth-of-type(54),
.xt-text:nth-of-type(55):hover + .xt-text:nth-of-type(56),
.xt-text:nth-of-type(42):hover,
.xt-text:nth-of-type(44):hover,
.xt-text:nth-of-type(46):hover,
.xt-text:nth-of-type(48):hover,
.xt-text:nth-of-type(50):hover,
.xt-text:nth-of-type(52):hover,
.xt-text:nth-of-type(54):hover,
.xt-text:nth-of-type(56):hover {
    max-height: 1000px !important;
    padding: 22px 20px 28px 56px !important;
    border-left-color: #0a0a0a !important;
}

/* 页脚 */
.xt-text:nth-of-type(57) {
    position: relative !important;
    margin: 60px 12px 8px 12px !important;
    padding: 40px 0 12px 0 !important;
    border-top: 1px solid #d0d0d0 !important;
    text-align: center !important;
    color: #0a0a0a !important;
    font-size: 22px !important;
    letter-spacing: 14px !important;
    font-family: 'Didot', 'Bodoni MT', 'Georgia', serif !important;
    font-weight: 300 !important;
}
.xt-text:nth-of-type(58) {
    margin: 8px 12px 0 12px !important;
    text-align: center !important;
    color: #606060 !important;
    font-size: 11px !important;
    font-family: 'Snell Roundhand', 'Segoe Script', 'Georgia', cursive !important;
    font-style: italic !important;
    letter-spacing: 1px !important;
}
.xt-text:nth-of-type(59) {
    padding: 12px 12px 40px 12px !important;
    text-align: center !important;
    color: #a0a0a0 !important;
    font-size: 8px !important; letter-spacing: 5px !important;
    font-family: 'Georgia', serif !important;
}

